NY (ARRAY['super_agent'::text, 'agent'::text, 'sub_agent'::text]))","foreign_columns":null,"initially_deferred":false,"referenced_relation":null},{"name":"agents_status_check","type":"c","columns":[6],"validated":true,"deferrable":false,"definition":"CHECK (status = ANY (ARRAY['active'::text, 'suspended'::text, 'frozen'::text]))","foreign_columns":null,"initially_deferred":false,"referenced_relation":null},{"name":"check_credit","type":"c","columns":[11,10,12],"validated":true,"deferrable":false,"definition":"CHECK (credit_used <= credit_limit OR is_prepaid = true)","foreign_columns":null,"initially_deferred":false,"referenced_relation":null},{"name":"chk_player_wallet_balance_is_two_decimal_places","type":"c","columns":[29],"validated":true,"deferrable":false,"definition":"CHECK (player_wallet_balance IS NULL OR player_wallet_balance = round(player_wallet_balance, 2))","foreign_columns":null,"initially_deferred":false,"referenced_relation":null},{"name":"fk_agents_parent","type":"f","columns":[7],"validated":true,"deferrable":false,"definition":"FOREIGN KEY (parent_agent_id) REFERENCES agents(id)","foreign_columns":[1],"initially_deferred":false,"referenced_relation":"agents"},{"name":"fk_agents_user_id_profiles","type":"f","columns":[2],"validated":true,"deferrable":false,"definition":"FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE","foreign_columns":[1],"initially_deferred":false,"referenced_relation":"profiles"}],"inheritance":null,"partition_key":null,"partition_bound":null,"replica_identity":"d","effective_privileges":{"anon":{"table":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":true,"MAINTAIN":true,"TRUNCATE":false,"REFERENCES":true},"any_column":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":true}},"service_role":{"table":{"DELETE":true,"INSERT":true,"SELECT":true,"UPDATE":true,"TRIGGER":true,"MAINTAIN":true,"TRUNCATE":true,"REFERENCES":true},"any_column":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true}},"authenticated":{"table":{"DELETE":false,"INSERT":false,"SELECT":true,"UPDATE":false,"TRIGGER":true,"MAINTAIN":true,"TRUNCATE":false,"REFERENCES":true},"any_column":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true}}}}$catalog$::jsonb;
 actual jsonb;required jsonb;item jsonb;pass integer;target oid:='public.agents'::regclass;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(expected->'indexes') WHERE (value->>'unique')::boolean IS FALSE LOOP
  IF to_regclass('public.'||(item->>'name')) IS NOT NULL THEN
   RAISE EXCEPTION 'credit fixture secondary index preexists' USING DETAIL=item->>'name';END IF;
 END LOOP;
 FOR pass IN 1..2 LOOP
  SELECT jsonb_build_object(
   'schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'kind',c.relkind,
   'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'partition',c.relispartition,
   'partition_key',CASE WHEN c.relkind='p' THEN pg_get_partkeydef(c.oid) END,
   'partition_bound',pg_get_expr(c.relpartbound,c.oid),'replica_identity',c.relreplident,
   'acl',(SELECT jsonb_agg(z::text ORDER BY z::text) FROM unnest(c.relacl)z),'options',c.reloptions,
   'columns',(SELECT jsonb_agg(jsonb_build_object(
    'name',a.attname,'ordinal',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,
    'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,
    'acl',a.attacl,'collation',CASE WHEN a.attcollation<>0 THEN a.attcollation::regcollation::text END,
    'effective_privileges',(SELECT jsonb_object_agg(api,jsonb_build_object(
      'SELECT',has_column_privilege(api,c.oid,a.attnum,'SELECT'),
      'INSERT',has_column_privilege(api,c.oid,a.attnum,'INSERT'),
      'UPDATE',has_column_privilege(api,c.oid,a.attnum,'UPDATE'),
      'REFERENCES',has_column_privilege(api,c.oid,a.attnum,'REFERENCES')))
      FROM unnest(ARRAY['anon','authenticated','service_role'])api))
    ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
    WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
   'constraints',(SELECT jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,
    'definition',pg_get_constraintdef(k.oid,true),'validated',k.convalidated,'deferrable',k.condeferrable,
    'initially_deferred',k.condeferred,'columns',k.conkey,'foreign_columns',k.confkey,
    'referenced_relation',CASE WHEN k.confrelid<>0 THEN k.confrelid::regclass::text END)
    ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),
   'indexes',(SELECT jsonb_agg(jsonb_build_object('name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),
    'owner',pg_get_userbyid(ci.relowner),'kind',ci.relkind,'unique',i.indisunique,'primary',i.indisprimary,
    'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'immediate',i.indimmediate,
    'replica_identity',i.indisreplident,'clustered',i.indisclustered,'nulls_not_distinct',i.indnullsnotdistinct)
    ORDER BY ci.relname) FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=c.oid),
   'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),
    'enabled',t.tgenabled,'internal',t.tgisinternal,'type',t.tgtype,'function',t.tgfoid::regprocedure::text,
    'function_definition_md5',md5(pg_get_functiondef(t.tgfoid)),
    'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,
    'acl',(SELECT jsonb_agg(z::text ORDER BY z::text) FROM unnest(p.proacl)z),
    'deferrable',t.tgdeferrable,'initially_deferred',t.tginitdeferred)
    ORDER BY t.tgname) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid=c.oid AND NOT t.tgisinternal),
   'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.policyname) FROM pg_policies p WHERE p.schemaname=n.nspname AND p.tablename=c.relname),
   'inheritance',(SELECT jsonb_agg(jsonb_build_object('parent',i.inhparent::regclass::text,'child',i.inhrelid::regclass::text,'sequence',i.inhseqno)
    ORDER BY i.inhparent::regclass::text,i.inhrelid::regclass::text) FROM pg_inherits i WHERE c.oid IN(i.inhparent,i.inhrelid)),
   'effective_privileges',(SELECT jsonb_object_agg(api,jsonb_build_object(
    'table',(SELECT jsonb_object_agg(priv,has_table_privilege(api,c.oid,priv)) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'])priv),
    'any_column',(SELECT jsonb_object_agg(priv,has_any_column_privilege(api,c.oid,priv)) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','REFERENCES'])priv)))
    FROM unnest(ARRAY['anon','authenticated','service_role'])api)
  ) INTO actual FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=target;
  required:=expected;
  IF pass=1 THEN
   required:=jsonb_set(expected,'{indexes}',(SELECT jsonb_agg(value ORDER BY value->>'name')
     FROM jsonb_array_elements(expected->'indexes') WHERE (value->>'unique')::boolean IS TRUE));
  END IF;
  IF actual IS DISTINCT FROM required THEN
   RAISE EXCEPTION 'credit fixture agent catalog changed' USING DETAIL='pass='||pass::text;
  END IF;
  IF pass=1 THEN
   FOR item IN SELECT value FROM jsonb_array_elements(expected->'indexes') WHERE (value->>'unique')::boolean IS FALSE LOOP
    -- Exact source-owned captured CREATE INDEX, never caller text or a fallback.
    EXECUTE item->>'definition';
   END LOOP;
  END IF;
 END LOOP;
END$bootstrap$;
COMMIT;
